// SPIKE (Phase 0, data layer): TableSpec → static Drizzle schema source for drizzle-kit.
// Must produce exactly the same tables as drizzle-runtime.ts.
import type { ColumnSpec, TableSpec } from './schema-spec.ts';

const ident = (s: string) => (/^[A-Za-z_$][\w$]*$/.test(s) ? s : JSON.stringify(s));
const varName = (s: string) => `t_${s.replace(/\W/g, '_')}`;

export function generateDrizzleSchema(specs: TableSpec[]): string {
	const out = [
		'// GENERATED by kitcms from kitcms.config.ts. Do not edit.',
		"import { index, integer, real, sqliteTable, text, uniqueIndex, type AnySQLiteColumn } from 'drizzle-orm/sqlite-core';",
		'',
	];
	for (const spec of specs) {
		const cols = spec.columns.map((c) => `\t${ident(c.name)}: ${columnSrc(c)},`).join('\n');
		const idx = spec.indexes
			.map(
				(ix) =>
					`\t${ix.unique ? 'uniqueIndex' : 'index'}(${JSON.stringify(ix.name)}).on(${ix.columns
						.map((n) => `t[${JSON.stringify(n)}]`)
						.join(', ')}),`,
			)
			.join('\n');
		out.push(
			`export const ${varName(spec.name)} = sqliteTable(${JSON.stringify(spec.name)}, {\n${cols}\n}, (t) => [\n${idx}\n]);`,
			'',
		);
	}
	return out.join('\n');
}

function columnSrc(c: ColumnSpec): string {
	const n = JSON.stringify(c.name);
	let s = {
		text: `text(${n})`,
		json: `text(${n}, { mode: 'json' })`,
		real: `real(${n})`,
		integer: `integer(${n})`,
		boolean: `integer(${n}, { mode: 'boolean' })`,
		timestamp: `integer(${n}, { mode: 'timestamp_ms' })`,
	}[c.kind];
	if (c.primaryKey) s += '.primaryKey()';
	if (c.notNull) s += '.notNull()';
	if (c.default !== undefined) s += `.default(${JSON.stringify(c.default)})`;
	if (c.references) {
		s += `.references((): AnySQLiteColumn => ${varName(c.references.table)}.id, { onDelete: ${JSON.stringify(c.references.onDelete)} })`;
	}
	return s;
}
